/// <summary>
/// N.Freidenberger 29.01.2025
/// </summary>
internal final class AVAReassignItemToNewProductService extends SysOperationServiceBase
{

    EcoResProduct                       newEcoResProduct;
    EcoResProduct                       oldEcoResProduct;
    InventTable                         inventTable;
}

Method.Source:
    /// <summary>
/// N.Freidenberger 29.01.2025
/// </summary>
/// <param name = "_contract">_contract</param>
public void process(AVAReassignItemToNewProductContract     _contract)  
{
    inventTable     = _contract.parmInventTable();
    EcoResProductDisplayProductNumber   newProductNum   = _contract.parmNewProduct();

    CostItemsMissingCostingDataDataSetTable  costItemsMissingCostingDataDataSetTable;
    InventDistinctProduct                    inventDistinctProduct;
    EcoResProductReleasedRecentlyCreatedDataSetTable ecoResProductReleasedRecentlyCreatedDataSetTable;
    EntAssetObjectItem                       entAssetObjectItem;
    CostItemsMissingCostDataSetTable         costItemsMissingCostDataSetTable;
    MCRUpSellItem                            mCRUpSellItem;
    TradeNonStockedConversionItem            tradeNonStockedConversionItem;
    EngChgProductReleaseProduct              engChgProductReleaseProduct;
    EngChgEcmProductRelease                  engChgEcmProductRelease;
    RetailProductListingStatus               retailProductListingStatus;
    ReqDemPlanForecastChangeEntry            reqDemPlanForecastChangeEntry;
    EngChgProductReadinessCheck              engChgProductReadinessCheck;
    KCS_CALCalcProduct                       kcs_CALCalcProduct;
    ReqDemPlanCubeStagingTable               reqDemPlanCubeStagingTable;
    ReqDemPlanForecast                       reqDemPlanForecast;
    ReqPO                                    reqPO;     
    EngChgEcmProduct                         engChgEcmProduct;


    newEcoResProduct = EcoResProduct::findByProductNumber(newProductNum);
    oldEcoResProduct = EcoResProduct::find(inventTable.Product);


    if (!this.checkProduct())
    {
        return;
    }

    ttsbegin;

    inventTable.selectForUpdate(true);
    inventTable.Product = newEcoResProduct.RecId;
    if (inventTable.RecId)
    {
        inventTable.doUpdate();
    }

    while select  forupdate  costItemsMissingCostingDataDataSetTable
        where costItemsMissingCostingDataDataSetTable.Product == oldEcoResProduct.RecId
    {
        costItemsMissingCostingDataDataSetTable.Product = newEcoResProduct.RecId;
        costItemsMissingCostingDataDataSetTable.doUpdate();
    }

    while select  forupdate  inventDistinctProduct
        where inventDistinctProduct.Product == oldEcoResProduct.RecId
    {
        inventDistinctProduct.Product = newEcoResProduct.RecId;
        inventDistinctProduct.doUpdate();
    }



    while select  forupdate  ecoResProductReleasedRecentlyCreatedDataSetTable
        where ecoResProductReleasedRecentlyCreatedDataSetTable.Product == oldEcoResProduct.RecId
    {
        ecoResProductReleasedRecentlyCreatedDataSetTable.Product = newEcoResProduct.RecId;
        ecoResProductReleasedRecentlyCreatedDataSetTable.doUpdate();
    }

    while select  forupdate  entAssetObjectItem
        where entAssetObjectItem.Product == oldEcoResProduct.RecId
    {
        entAssetObjectItem.Product = newEcoResProduct.RecId;
        entAssetObjectItem.doUpdate();
    }

    while select  forupdate  costItemsMissingCostDataSetTable
        where costItemsMissingCostDataSetTable.Product == oldEcoResProduct.RecId
    {
        costItemsMissingCostDataSetTable.Product = newEcoResProduct.RecId;
        costItemsMissingCostDataSetTable.doUpdate();
    }

    while select  forupdate  mCRUpSellItem
        where mCRUpSellItem.Product == oldEcoResProduct.RecId
    {
        mCRUpSellItem.Product = newEcoResProduct.RecId;
        mCRUpSellItem.doUpdate();
    }

    while select  forupdate  tradeNonStockedConversionItem
        where tradeNonStockedConversionItem.Product == oldEcoResProduct.RecId
    {
        tradeNonStockedConversionItem.Product = newEcoResProduct.RecId;
        tradeNonStockedConversionItem.doUpdate();
    }

    while select  forupdate  engChgProductReleaseProduct
        where engChgProductReleaseProduct.Product == oldEcoResProduct.RecId
    {
        engChgProductReleaseProduct.Product = newEcoResProduct.RecId;
        engChgProductReleaseProduct.doUpdate();
    }

    while select  forupdate  engChgEcmProductRelease
        where engChgEcmProductRelease.Product == oldEcoResProduct.RecId
    {
        engChgEcmProductRelease.Product = newEcoResProduct.RecId;
        engChgEcmProductRelease.doUpdate();
    }

    while select  forupdate  retailProductListingStatus
        where retailProductListingStatus.Product == oldEcoResProduct.RecId
    {
        retailProductListingStatus.Product = newEcoResProduct.RecId;
        retailProductListingStatus.doUpdate();
    }

    while select  forupdate  reqDemPlanForecastChangeEntry
        where reqDemPlanForecastChangeEntry.Product == oldEcoResProduct.RecId
    {
        reqDemPlanForecastChangeEntry.Product = newEcoResProduct.RecId;
        reqDemPlanForecastChangeEntry.doUpdate();
    }

    while select  forupdate  engChgProductReadinessCheck
        where engChgProductReadinessCheck.Product == oldEcoResProduct.RecId
    {
        engChgProductReadinessCheck.Product = newEcoResProduct.RecId;
        engChgProductReadinessCheck.doUpdate();
    }

    while select  forupdate  kcs_CALCalcProduct
        where kcs_CALCalcProduct.Product == oldEcoResProduct.RecId
    {
        kcs_CALCalcProduct.Product = newEcoResProduct.RecId;
        kcs_CALCalcProduct.doUpdate();
    }

    while select  forupdate  reqDemPlanCubeStagingTable
        where reqDemPlanCubeStagingTable.Product == oldEcoResProduct.RecId
    {
        reqDemPlanCubeStagingTable.Product = newEcoResProduct.RecId;
        reqDemPlanCubeStagingTable.doUpdate();
    }

    while select  forupdate  reqDemPlanForecast
        where reqDemPlanForecast.Product == oldEcoResProduct.RecId
    {
        reqDemPlanForecast.Product = newEcoResProduct.RecId;
        reqDemPlanForecast.doUpdate();
    }

    while select  forupdate  reqPO
        where reqPO.Product == oldEcoResProduct.RecId
    {
        reqPO.Product = newEcoResProduct.RecId;
        reqPO.doUpdate();
    }

    while select  forupdate  engChgEcmProduct
        where engChgEcmProduct.Product == oldEcoResProduct.RecId
    {
        engChgEcmProduct.Product = newEcoResProduct.RecId;
        engChgEcmProduct.doUpdate();
    }

    this.writeLog();

    ttscommit;

    FormDataSource      inventTableDS = inventTable.dataSource();

    if (inventTableDS)
    {
        InventTable     locInventTable;
        locInventTable.data(inventTable);

        inventTableDS.executeQuery();
        inventTableDS.positionToRecord(locInventTable);
    }


}

/// <summary>
/// N.Freidenberger 01.02.2025
/// </summary>
/// <returns>boolean</returns>
public boolean  checkProduct()
{

    boolean   ret = true;
    InventTable     locInventTable = InventTable::findByProduct(newEcoResProduct.RecId);

    if (locInventTable.RecId)
    {
        ret = checkFailed("@NDX:NXAProdIsAlreadzUsed");
    }

    EcoResProductDimensionGroupProduct      oldEcoResPrdDimGrpPrd = EcoResProductDimensionGroupProduct::findByProduct(oldEcoResProduct.RecId);
    EcoResProductDimensionGroupProduct      newEcoResPrdDimGrpPrd = EcoResProductDimensionGroupProduct::findByProduct(newEcoResProduct.RecId);

    if(newEcoResProduct.ProductType  != oldEcoResProduct.ProductType
    || newEcoResProduct.ServiceType  != oldEcoResProduct.ServiceType
    || newEcoResPrdDimGrpPrd.ProductDimensionGroup !=  oldEcoResPrdDimGrpPrd.ProductDimensionGroup)
    {
        ret =  checkFailed("@NDX:NXAProdCopyCheckError");
    }

    return ret;
}

/// <summary>
/// N.Freidenberger 04.02.2025
/// </summary>
public void writeLog()
{
    AVAReassignItemToNewProductLog      log;

    log.ItemId          = inventTable.ItemId;
    log.ProductNew      = newEcoResProduct.RecId;
    log.ProductNumNew   = newEcoResProduct.DisplayProductNumber;
    log.ProductOld      = oldEcoResProduct.RecId;
    log.ProductNumOld   = oldEcoResProduct.DisplayProductNumber;
    log.UserId          = curUserId();
    log.ChangeDateTime  = DateTimeUtil::getSystemDateTime();
    log.insert();
}
